def smallest_from_leaf(root):
    best, path = None, []

    def dfs(node):
        nonlocal best
        if node is None:
            return
        path.append(chr(ord("a") + node.val))
        if node.left is None and node.right is None:
            s = "".join(reversed(path))
            if best is None or s < best:
                best = s
        dfs(node.left)
        dfs(node.right)
        path.pop()

    dfs(root)
    return best
